@spec tracker_page_spec  src=tests/specs/tracker_page_spec.lua  loc=1414  cases=44
@exercises tuning (tuning), configManager (h.cm), commandManager (h.cmgr), midiManager (h.mm), trackerManager (h.tm)
@surface   tuning.derive, tuning.genDiamond, cm:setContext, cmgr:push, cmgr:invoke, cm:getAt, cm:set, cm:get, tuning.stepToMidi, mm:subscribe, mm:notes, tm:assignEvent, tm:byUuid, tm:flush
@harness   mk, reaper:addItem, reaper:setProjectTracks, reaper:seedMidi

# Intent
  Pin-tests for trackerPage's Page interface (bind / unbind / focusState /
  bind-from-cursor) and the retune modal's slots, defaults and dispatch.
  render / handleInput are stubs wired in step 3 and verified in REAPER, not here.

# Helpers
  @fn resetArrange()  @ 59-153
  @fn seedItems(h, takes, srcLen)  @ 169-174
      -- A bind re-keys cm's track tier off the take's own item, so a take named in
      -- fakeArrange needs one in the fake project too.
  @fn newTrackerPage(cm, ds, cmgr, chrome, gui)  @ 176-185
  @fn trackList(trackCount)  @ 187-193
  @fn mapTracker(harness, inst, trackCount)  @ 197-211
      -- A tracker bound to the take 'i0' over a track list of the given width, with
      -- i0's placement as the caller states it; inst = nil binds it into no instance.

# Cases
  @case 'bind(take) drives cm:setContext via the page's own tm:bindTake'  [harness]  @ 215-223
  @case 'unbind() drives cm:setContext(nil) via the page's own tm:bindTake'  [harness]  @ 226-235
  @case 'focusState before any render returns both bits false'  [harness]  @ 238-245
  @case 'bindFromSelection binds tm to the resolved selection take, drops when the track has no slots'  [harness]  @ 251-264
  @case 'with no live instance, the new take mints a parked slot and selects it'  [harness]  @ 268-285
  @case 'deleteBoundSlot confirms, then deletes the bound slot through the arrange facade'  [harness]  @ 291-312
  @case 'take properties renames the bound take\'s slot, not that one take'  [harness]  @ 318-336
  @case 'take properties follows the bound take when the tracker sits on another slot'  [harness]  @ 343-361
  @case 'the new take places below the current instance and becomes current'  [harness]  @ 367-400
  @case 'a new take on a just-selected track parks, rather than appending on the old one'  [harness]  @ 404-428
  @case 'duplicate below appends another instance of the bound slot and makes it current'  [harness]  @ 434-464
  @case 'duplicate below refuses where the free span falls short'  [harness]  @ 468-489
  @case 'duplicate below on a slot whose only take is parked does nothing'  [harness]  @ 493-506
  @case 'the variant step rebinds the tracker to the slot stepped to and follows its placement'  [harness]  @ 512-546
  @case 'a variant step with the tracker in no instance does nothing'  [harness]  @ 550-564
  @case 'prev/next track + take drive the tv selection, not the arrange cursor'  [harness]  @ 568-591
  @case 'F6 plays from the instance dived into, not the placement the bind resolved'  [harness]  @ 598-615
  @case 'a dive outranks a play head already sitting in another instance'  [harness]  @ 619-642
  @case 'the play head entering an instance makes it current; leaving one writes nothing'  [harness]  @ 646-669
  @case 'a slot change seeks from the outgoing instance, backwards for prevTake'  [harness]  @ 673-708
  @case 'the walk steps along the track's placements in start order, holding at the ends'  [harness]  @ 712-760
  @case 'a walk into another slot resets the caret; within one slot the caret holds'  [harness]  @ 764-801
  @case 'a slot with no live instance leaves the tracker nowhere, and F6 silent'  [harness]  @ 805-821
  @case 'the map window centres the bound column, and clamps it at both ends'  [harness]  @ 830-848
  @case 'the map window centres time on the current instance, holding its top on screen'  [harness]  @ 852-864
  @case 'with the tracker in no instance the map window centres on the edit cursor'  [harness]  @ 868-875
  @case 'the map window carries the takes over it, the current instance marked'  [harness]  @ 879-890
  @case 'the play row is the head\'s offset into the current instance, in rows'  [harness]  @ 894-921
  @case 'the play row dims where the head is sounding a sibling instance'  [harness]  @ 925-949
  @case 'the cut row is where the rendered span stops short of the source'  [harness]  @ 956-977
  @case 'the play row and the head row count from the source origin, not the start'  [harness]  @ 983-1007
  @case 'a dive carries the arrange QN to the caret row, and the caret hands it back'  [harness]  @ 1014-1033
  @case 'a caret outside the rendered span hands back the row the span stops at'  [harness]  @ 1037-1056
  @case 'leaving the tracker puts the arrange caret where the tracker caret is'  [harness]  @ 1060-1082
  @case 'with loop to item on, a dive brackets the instance dived into'  [harness]  @ 1088-1106
  @case 'the play head entering an instance leaves the loop where it was'  [harness]  @ 1110-1128
  @case 'the toggle command brackets the current instance as it comes on'  [harness]  @ 1132-1154
  @case 'the loop-to-item verb brackets the current instance, toggle or no toggle'  [harness]  @ 1158-1182
  @case 'retune opens on the scope the selection implies and OK snaps that scope'  [harness]  @ 1188-1243
  @case 'retune opens on the facility the take carries, its dials on their figures'  [harness]  @ 1251-1280
  @case 'a refused retune offers to widen, and the offer taken solves again'  [harness]  @ 1286-1329
  @case 'empty grid shows the single no-takes message'  [harness]  @ 1335-1349
  @case 'an owned tm flush resyncs the watcher baseline; only a foreign write trips the reload'  [harness]  @ 1356-1388
  @case 'bindFromSelection re-keys cm on return from dormancy even when the take is unchanged'  [harness]  @ 1392-1412

